FILE: sys/arch/rp2040/rp2040/exec_hsaout.c

1	/*
2	 * Loader for packed a.out executables, sys/exec_hsaout.h. The checker
3	 * recognizes its format by the EX_HSPACK flag alone; from then on every
4	 * failure is EFTYPE, a verdict the exec dispatcher passes through, so a
5	 * damaged container is never handed to the next format. It preflights
6	 * both streams into a discard buffer while the old image is intact,
7	 * commits the process only once the lengths and CRCs have been
8	 * reproduced, and then expands again into the user window, where a
9	 * second mismatch kills the process before any of its bytes run.
10	 */
11	#include <sys/param.h>
12	#include <sys/systm.h>
13	#include <sys/map.h>
14	#include <sys/inode.h>
15	#include <sys/user.h>
16	#include <sys/proc.h>
17	#include <sys/buf.h>
18	#include <sys/namei.h>
19	#include <sys/fs.h>
20	#include <sys/mount.h>
21	#include <sys/file.h>
22	#include <sys/resource.h>
23	#include <sys/exec.h>
24	#include <sys/exec_hsaout.h>
25	#include <sys/dir.h>
26	#include <sys/uio.h>
27	#include <sys/signal.h>
28	#include <machine/hsx_decoder.h>
29	#include <machine/debug.h>
30	#ifdef SWAPRAM
31	#include <machine/swapram.h>
32	#endif
