34	_Static_assert (HSX_WORK_SIZE <= MAXBSIZE,
35	    "the decoder work area must fit one buffer cache block");
36	#ifdef SWAPRAM
37	_Static_assert (sizeof (struct hsx_work) <= SWAPRAM_CODEC_WORK_BYTES,
38	    "the packed-text decoder must fit the shared codec workspace");
39	#endif
