41	/* Read len packed bytes at off from the executable; short is an error. */
42	static int
43	hsx_fill (void *ctx, unsigned off, void *buf, unsigned len)
44	{
45	    int resid = 0, error;
46	
47	    error = rdwri (UIO_READ, (struct inode *) ctx, (caddr_t) buf, (int) len,
48	        (off_t) off, IO_UNIT, &resid);
49	    return (error != 0 || resid != 0) ? -1 : 0;
50	}
51	
52	/*
53	 * Expand one stream from the executable into dst (null discards) and
54	 * compare its length and CRC with what the header promised, using the
55	 * caller's decoder work area.
56	 */
57	static int
58	hsx_load (struct hsx_work *w, struct inode *ip, unsigned off, unsigned clen,
59	    caddr_t dst, unsigned rlen, unsigned want)
60	{
61	    unsigned crc = 0;
62	    int r;
63	
64	    r = hsx_expand (w, hsx_fill, ip, off, clen, (unsigned char *) dst, rlen,
65	        &crc);
66	    return (r == 0 && crc == want) ? 0 : -1;
67	}
68	
69	/*
70	 * exec runs in a process and its rdwri sleeps, which can schedule another
71	 * exec; each therefore expands into a buffer cache block it holds for the
72	 * call, so two concurrent execs never share decoder state. The block is
73	 * freed on every path out of exec_hsaout_check.
74	 */
75	static int
76	hsx_load_buf (struct buf *bp, struct inode *ip, unsigned off, unsigned clen,
77	    caddr_t dst, unsigned rlen, unsigned want)
78	{
79	    return hsx_load ((struct hsx_work *) bp->b_addr, ip, off, clen, dst,
80	        rlen, want);
81	}
