83	/* Read struct hsx from behind struct exec and validate both headers. */
84	static int
85	hsx_headers (struct inode *ip, const struct exec *e, struct hsx *x)
86	{
87	    int resid = 0;
88	
89	    if (rdwri (UIO_READ, ip, (caddr_t) x, sizeof *x,
90	        (off_t) sizeof (struct exec), IO_UNIT, &resid) != 0 || resid != 0)
91	        return HSX_BADSIZE;
92	    return hsx_check (e, x, (unsigned long) ip->i_size);
93	}
94	
95	int
96	exec_hsaout_check (struct exec_params *epp)
97	{
98	    struct proc *p = u.u_procp;
99	    struct exec raw;
100	    struct hsx x;
101	    struct buf *bp;
102	    unsigned toff, doff;
103	    int error, thumb;
104	
105	    if (epp->hdr_len < (int) sizeof (struct exec))
106	        return ENOEXEC;
107	    if (N_GETMAGIC (epp->hdr.aout) != OMAGIC ||
108	        N_GETFLAG (epp->hdr.aout) != EX_HSPACK)
109	        return ENOEXEC;         /* another format's file */
110	
111	    /*
112	     * Recognized. The headers, then the raw layout with the flag masked:
113	     * the raw check's file size test is skipped because the container is
114	     * shorter than its image, and hsx_check has already demanded the
115	     * exact packed size.
116	     */
117	    if (hsx_headers (epp->ip, &epp->hdr.aout, &x) != HSX_OK) {
118	        DEBUG ("\texec_hsaout_check(): bad container header\n");
119	        return EFTYPE;
120	    }
121	    raw = epp->hdr.aout;
122	    N_SETMAGIC (raw, OMAGIC, MID_ZERO, 0);
123	#if defined(__thumb__) || defined(__thumb2__)
124	    thumb = 1;
125	#else
126	    thumb = 0;
127	#endif
128	    error = aout_layout_check (&raw, (unsigned) __user_data_start,
129	        (unsigned) USER_WINDOW_MAX,
130	        (unsigned long) sizeof (struct exec) + raw.a_text + raw.a_data,
131	        thumb);
132	    if (error != AOUT_OK) {
133	        DEBUG ("\texec_hsaout_check(): layout check %d\n", error);
134	        return error == AOUT_TOOBIG ? ENOMEM : EFTYPE;
135	    }
136	
137	    /*
138	     * Nobody writes the file from here on: the exclusion outlives this
139	     * call through p_tip once the process commits, and every rejection
140	     * below releases it.
141	     */
142	    if ((error = exec_text_hold (epp->ip)) != 0)
143	        return error;
144	
145	    /*
146	     * Preflight: both streams reproduced into the discard buffer. The
147	     * buffer cache block holds the decoder from here until this call
148	     * returns.
149	     */
150	    bp = geteblk ();
151	    toff = (unsigned) HSX_HDRSIZE;
152	    doff = toff + x.x_ctext;
153	    if (hsx_load_buf (bp, epp->ip, toff, x.x_ctext, NULL, raw.a_text,
154	        x.x_textcrc) != 0 ||
155	        hsx_load_buf (bp, epp->ip, doff, x.x_cdata, NULL, raw.a_data,
156	        x.x_datacrc) != 0) {
157	        DEBUG ("\texec_hsaout_check(): preflight failed\n");
158	        brelse (bp);
159	        exec_text_unhold (epp->ip);
160	        return EFTYPE;
161	    }
162	
163	    if ((error = exec_save_args (epp)) != 0) {
164	        brelse (bp);
165	        exec_text_unhold (epp->ip);
166	        return error;
167	    }
168	
169	    /* The same single-segment layout as a raw OMAGIC image. */
170	    epp->text.vaddr = epp->heap.vaddr = NO_ADDR;
171	    epp->text.len = epp->heap.len = 0;
172	    epp->data.vaddr = (caddr_t) __user_data_start;
173	    epp->data.len = raw.a_text + raw.a_data;
174	    epp->bss.vaddr = epp->data.vaddr + epp->data.len;
175	    epp->bss.len = raw.a_bss;
176	    epp->heap.vaddr = epp->bss.vaddr + epp->bss.len;
177	    epp->heap.len = 0;
178	    epp->stack.len = SSIZE + roundup (epp->argbc + epp->envbc, NBPW) +
179	        (epp->argc + epp->envc + 4) * NBPW;
180	    epp->stack.vaddr = (caddr_t) USER_TOP (p) - epp->stack.len;
181	
182	    if ((error = exec_estab (epp)) != 0) {
183	        brelse (bp);
184	        exec_text_unhold (epp->ip);
185	        return error;
186	    }
187	
188	    /*
189	     * Committed: the old image is gone. The executable is retained as
190	     * p_tip before the second pass so a failure here leaves the process
191	     * with its text reference and the exclusion in place for exit to
192	     * release; SIGKILL keeps the half-written window from ever running.
193	     */
194	    exec_text_release (p, epp->ip);
195	    epp->ip->i_count++;
196	    p->p_tip = epp->ip;
197	    p->p_tsize = raw.a_text;
198	
199	    if (hsx_load_buf (bp, epp->ip, toff, x.x_ctext, epp->data.vaddr,
200	        raw.a_text, x.x_textcrc) != 0 ||
201	        hsx_load_buf (bp, epp->ip, doff, x.x_cdata,
202	        epp->data.vaddr + raw.a_text, raw.a_data, x.x_datacrc) != 0) {
203	        brelse (bp);
204	        printf ("pid %d: packed executable changed between passes\n",
205	            p->p_pid);
206	        psignal (p, SIGKILL);
207	        return EFTYPE;
208	    }
209	    brelse (bp);
210	
211	    exec_clear (epp);
212	    exec_setupstack (raw.a_entry, epp);
213	    return 0;
214	}
