216	/*
217	 * The clean text for swapin: expand the text stream of the executable
218	 * behind e, which the caller has read and holds locked, into dst. len is
219	 * the text size the process was loaded with, and the header must still
220	 * agree with it.
221	 */
222	int
223	exec_hsaout_text (struct inode *ip, const struct exec *e, char *dst,
224	    unsigned len)
225	{
226	    struct hsx_work *swapwork;
227	    int result;
228	
229	    /*
230	     * swapin runs in the swapper, proc 0, whose getnewbuf would sleep on
231	     * a scarce buffer and stall the mechanism that frees memory. The
232	     * swapper is the only caller and never re-enters. A SwapRAM kernel uses
233	     * the owner-checked codec workspace because packed-text restoration and
234	     * SwapRAM expansion are consecutive stages of the same swapin. A swapout
235	     * scheduled while rdwri sleeps observes the packed-text owner and uses
236	     * flash until restoration releases the workspace.
237	     */
238	#ifndef SWAPRAM
239	    static struct hsx_work private_swapwork;
240	#endif
241	    struct hsx x;
242	
243	    if (hsx_headers (ip, e, &x) != HSX_OK || e->a_text != len)
244	        return -1;
245	#ifdef SWAPRAM
246	    swapwork = swapram_codec_acquire (SWAPRAM_CODEC_PACKED_TEXT);
247	#else
248	    swapwork = &private_swapwork;
249	#endif
250	    result = hsx_load (swapwork, ip, (unsigned) HSX_HDRSIZE, x.x_ctext,
251	        dst, len, x.x_textcrc);
252	#ifdef SWAPRAM
253	    swapram_codec_release (SWAPRAM_CODEC_PACKED_TEXT);
254	#endif
255	    return result;
256	}
